/// Returns the sign of a 32-bit signed integer:
/// 1 if positive, 0 if zero, -1 if negative.
fn sign_of(x: i32) -> i32 {
    if x > 0 {
        1
    } else if x < 0 {
        -1
    } else {
        0
    }
}

/// Given a vector of 32-bit signed integers, returns a new vector of the same length
/// in which each element is replaced by its sign.
fn sign(a: Vec<i32>) -> Vec<i32> {
    a.into_iter().map(sign_of).collect()
}

